from TTT import display_board


class Test_TttDisplayBoard(unittest.TestCase):

    @tag('smoke', 'regression', 'positive', 'valid')
    def test_display_board_orientation_mapping(self):
        """
        Validates that display_board maps indices to rows in correct orientation:
        - Top row uses indices 7,8,9
        - Middle row uses indices 4,5,6
        - Bottom row uses indices 1,2,3

        This is essential for accurate user display in a Tic-Tac-Toe interface, ensuring the
        printed board corresponds to the spatial layout players expect, which is core business logic.
        """
        # Arrange
        board = ['#', '1', '2', '3', '4', '5', '6', '7', '8', '9']  # index 0 unused; values equal their indices
        expected_lines = ["7|8|9", "4|5|6", "1|2|3"]

        # Act
        captured_stdout = io.StringIO()
        with redirect_stdout(captured_stdout):
            display_board(board)
        output_lines = [line.rstrip('\n') for line in captured_stdout.getvalue().splitlines()]

        # Assert
        self.assertEqual(
            output_lines,
            expected_lines,
            msg="Board orientation mismatch. Expected top/middle/bottom rows to map 7-8-9, 4-5-6, 1-2-3 respectively."
        )
        self.assertEqual(
            len(output_lines), 3, msg="display_board should print exactly three lines representing the three rows."
        )


